/**
 * V2-PHYS-INTEGRATION-01 (HPM 2026-10-18) — every PHYS switch off, the integrated planner and daily builder behave
 * EXACTLY like the production runtime (863f3fb), compared result for result.
 *
 * Enabled only when PHYS011_PREVIOUS_RUNTIME_ROOT points at a built checkout of the production release (its
 * planning-engine/dist); its compiled modules are imported read-only. Pure: no database.
 *
 * 1. Plans: one V2 plan per profile of a matrix (tiers, equipment, terrains, availability, recent history, a race),
 *    generated by both runtimes with no PHYS option → identical plans.
 * 2. Daily: every non-rest session of those plans, decided KEEP, MODIFY (lower load, shorter), REPLACE by every
 *    plannable kind (POWER, AEROBIC_INTERVALS and MOBILITY included), under no time limit and five time limits; and a
 *    manual session (P0-3) of every plannable kind and load, KEEP / MODIFY / REPLACE, same time limits → the same
 *    result (document, blocked reason, time constraint), or the same error.
 *
 * One intended difference, SPORT-SAFE-01 (HPM 2026-10-18, ADR A04 §6): where production returns a MODIFY whose sport
 * content is exactly the planned prescription's (the endurance session already at the LIGHT duration), the current
 * runtime refuses it (`modify_not_supported`). SPORT-SAFE-01R: the refusal is A04's outcome, so under any time limit the
 * time is not evaluated (`not_evaluated`), where production fitted the copy or adapted it (A10). Only that case
 * differs, and it is checked exactly.
 */
import { appendFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import * as current from "../../src/sessionModelV2/index.js";
import type { BuildFinalPrescriptionV2Input, PlanInputSnapshotV2, PlanSessionV2InMemory, PlanV2InMemory } from "../../src/sessionModelV2/index.js";
import type { PlanInputAvailabilityWindow } from "../../src/types/planInputSnapshot.js";

const PREVIOUS = process.env.PHYS011_PREVIOUS_RUNTIME_ROOT;
/** Optional: a file the case counts are appended to (vitest keeps the console quiet). */
const LOG = process.env.PHYS_EQUIVALENCE_LOG;
const note = (line: string) => LOG && appendFileSync(LOG, `${line}
`);
type Runtime = typeof current;
const production: Runtime | null = PREVIOUS ? ((await import(pathToFileURL(join(PREVIOUS, "planning-engine", "dist", "sessionModelV2", "index.js")).href)) as Runtime) : null;

function counter(prefix: string) {
  let n = 0;
  return () => `00000000-0000-4000-8000-${prefix}${String(++n).padStart(12 - prefix.length, "0")}`;
}
/** A result, or the error it throws (same message expected). */
function outcome<T>(run: () => T): T | { thrown: string } {
  try {
    return JSON.parse(JSON.stringify(run())) as T;
  } catch (error) {
    return { thrown: error instanceof Error ? `${error.name}: ${error.message}` : String(error) };
  }
}

const allDay: PlanInputAvailabilityWindow[] = [0, 1, 2, 3, 4, 5, 6].map((d) => ({ dayOfWeek: d as PlanInputAvailabilityWindow["dayOfWeek"], startTime: "08:00", endTime: "20:00" }));
const evenings: PlanInputAvailabilityWindow[] = [
  ...[1, 2, 3, 4, 5].map((d) => ({ dayOfWeek: d as PlanInputAvailabilityWindow["dayOfWeek"], startTime: "18:00", endTime: "19:30" })),
  ...[0, 6].map((d) => ({ dayOfWeek: d as PlanInputAvailabilityWindow["dayOfWeek"], startTime: "09:00", endTime: "17:00" })),
];
const BLOCK = { sequenceNumber: 1, name: "Plan", mode: "UNSPECIFIED" as const, primaryFocus: "Test", startDate: "2026-10-05", endDate: "2026-11-15" };

function snapshot(over: Partial<PlanInputSnapshotV2>): PlanInputSnapshotV2 {
  return {
    discipline: "Downhill",
    races: [],
    availability: { windows: allDay, exceptions: [] },
    equipment: ["dumbbells", "bench"],
    terrainAccess: ["flow_trail", "bermed_trail"],
    strengthExperienceTier: "intermediate",
    declaredLimitations: [],
    technicalPriorities: { strengths: [], weaknesses: [], priorityAreas: ["cornering", "braking"] },
    lockedDates: [],
    recentHistory: { recentSessionKinds: [], recentMissedOrReplacedCount: 0, trailingVolumeMinutes: 0 },
    dhTechnicalTier: "intermediate",
    ...over,
  };
}

const PROFILES: { name: string; snap: PlanInputSnapshotV2 }[] = [];
for (const tier of ["beginner", "intermediate", "advanced"] as const) {
  for (const equipment of [[], ["dumbbells", "bench"], ["dumbbells", "bench", "barbell", "kettlebell", "pull_up_bar"]]) {
    for (const terrainAccess of [["flow_trail", "bermed_trail"], ["flow_trail", "bermed_trail", "technical_trail", "full_dh_track", "bike_park"]]) {
      for (const [windowsName, windows] of [["all-day", allDay], ["evenings", evenings]] as const) {
        for (const trailingVolumeMinutes of [0, 240]) {
          PROFILES.push({
            name: `${tier}/${equipment.length}eq/${terrainAccess.length}terr/${windowsName}/${trailingVolumeMinutes}min`,
            snap: snapshot({ strengthExperienceTier: tier, dhTechnicalTier: tier, equipment, terrainAccess, availability: { windows, exceptions: [] }, recentHistory: { recentSessionKinds: [], recentMissedOrReplacedCount: trailingVolumeMinutes > 0 ? 0 : 3, trailingVolumeMinutes } }),
          });
        }
      }
    }
  }
}
PROFILES.push({
  name: "intermediate/race",
  snap: snapshot({ races: [{ id: "race-1", name: "Race", startDate: "2026-11-07", endDate: "2026-11-08", priority: "A" }] as unknown as PlanInputSnapshotV2["races"] }),
});

function plan(runtime: Runtime, snap: PlanInputSnapshotV2) {
  return outcome(() => runtime.generatePlanV2InMemory({ block: BLOCK, snapshot: snap, mintId: counter("a") }));
}

const REPLACE_TARGETS: BuildFinalPrescriptionV2Input["decision"]["finalSession"][] = [
  { kind: "STRENGTH_LOWER", loadProfile: "MODERATE" },
  { kind: "STRENGTH_LOWER", loadProfile: "LIGHT" },
  { kind: "STRENGTH_UPPER", loadProfile: "MODERATE" },
  { kind: "DH_TECHNICAL", loadProfile: "MODERATE", durationMin: 90 },
  { kind: "DH_TECHNICAL", loadProfile: "LIGHT", durationMin: 60 },
  { kind: "DH_LIGHT", loadProfile: "LIGHT", durationMin: 60 },
  { kind: "AEROBIC_BASE", loadProfile: "LIGHT", durationMin: 45 },
  { kind: "AEROBIC_BASE", loadProfile: "MODERATE", durationMin: 60 },
  { kind: "RECOVERY_ACTIVE", loadProfile: "LIGHT" },
  { kind: "POWER", loadProfile: "MODERATE" },
  { kind: "AEROBIC_INTERVALS", loadProfile: "MODERATE" },
  { kind: "AEROBIC_INTERVALS", loadProfile: "LIGHT" },
  { kind: "MOBILITY" },
  { kind: "GRIP_WORK", loadProfile: "MODERATE" },
  { kind: "PUMPTRACK", loadProfile: "MODERATE" },
  { kind: "STRENGTH_FULL_LIGHT", loadProfile: "LIGHT" },
];
const MANUAL_KINDS = ["DH_TECHNICAL", "DH_PERFORMANCE", "DH_LIGHT", "PUMPTRACK", "BIKE_MAINTENANCE", "STRENGTH_LOWER", "STRENGTH_UPPER", "STRENGTH_FULL_LIGHT", "POWER", "GRIP_WORK", "AEROBIC_BASE", "AEROBIC_INTERVALS", "MOBILITY", "RECOVERY_ACTIVE"];
const TIME_LIMITS = [null, 20, 30, 45, 60, 90] as const;
const LOWER: Record<string, "LIGHT" | "MODERATE"> = { HEAVY: "MODERATE", MODERATE: "LIGHT" };
const HIGHER: Record<string, "MODERATE" | "HEAVY"> = { LIGHT: "MODERATE", MODERATE: "HEAVY" };

/** SPORT-SAFE-01 — production's "modified" copy of the planned dose, and the refusal that replaces it. */
function unchangedModify(prod: unknown, s: PlanSessionV2InMemory, decision: string): prod is Extract<current.FinalPrescriptionWithinTodayTimeV2Result, { status: "created" }> {
  const r = prod as current.FinalPrescriptionWithinTodayTimeV2Result;
  return decision === "MODIFY" && r.status === "created" && current.canonicalSportContent(r.finalPrescription.structure) === current.canonicalSportContent(s.plannedPrescription.structure);
}
function refusalOf(copy: Extract<current.FinalPrescriptionWithinTodayTimeV2Result, { status: "created" }>, prod: current.FinalPrescriptionWithinTodayTimeV2Result, s: PlanSessionV2InMemory, finalSession: BuildFinalPrescriptionV2Input["decision"]["finalSession"]) {
  const before = prod.timeConstraint?.before;
  return {
    status: "blocked",
    code: "final_prescription_adaptation_not_defined",
    detail: { reason: "modify_not_supported", planned: s.loadProfile ?? null, final: finalSession.loadProfile ?? null, durationMin: copy.effectiveDurationMin ?? null },
    ...(prod.timeConstraint !== undefined ? { timeConstraint: { availableMinutes: prod.timeConstraint.availableMinutes, action: "not_evaluated", before, after: before } } : {}),
  };
}

function generatedInput(runtime: Runtime, p: PlanV2InMemory, s: PlanSessionV2InMemory, snap: PlanInputSnapshotV2, decision: "KEEP" | "MODIFY" | "REPLACE", finalSession: BuildFinalPrescriptionV2Input["decision"]["finalSession"], availableMinutes: number | null) {
  return {
    availableMinutes,
    finalPrescriptionId: "final-1",
    decision: { decisionId: "decision-1", decision, finalSession },
    lineage: {
      plannedSessionSource: "generated",
      sourcePlanVersionId: p.planVersionId,
      sourceGeneratedSessionId: s.generatedPlanSessionId,
      currentPlanVersionId: p.planVersionId,
      generatedSession: { id: s.generatedPlanSessionId, kind: s.kind, loadProfile: s.loadProfile ?? null, durationMin: s.durationMin },
    },
    plannedPrescription: { ...s.plannedPrescription, generatedPlanSessionId: s.generatedPlanSessionId, structure: JSON.parse(JSON.stringify(s.plannedPrescription.structure)) },
    adaptation: runtime.dailyAdaptationContextV2(snap, s.date, counter("b")),
  } as BuildFinalPrescriptionV2Input & { availableMinutes: number | null };
}

function manualInput(runtime: Runtime, p: PlanV2InMemory, snap: PlanInputSnapshotV2, date: string, decision: "KEEP" | "MODIFY" | "REPLACE", finalSession: BuildFinalPrescriptionV2Input["decision"]["finalSession"], availableMinutes: number | null, manualSession?: BuildFinalPrescriptionV2Input["decision"]["finalSession"]) {
  return {
    availableMinutes,
    finalPrescriptionId: "final-m",
    decision: { decisionId: "decision-m", decision, finalSession },
    lineage: { plannedSessionSource: "manual", sourcePlanVersionId: null, sourceGeneratedSessionId: null, currentPlanVersionId: p.planVersionId, generatedSession: null, currentPlanCoversDate: true, ...(manualSession !== undefined ? { manualSession } : {}) },
    plannedPrescription: null,
    adaptation: runtime.dailyAdaptationContextV2(snap, date, counter("m")),
  } as BuildFinalPrescriptionV2Input & { availableMinutes: number | null };
}

describe.skipIf(!production)("V2-PHYS-INTEGRATION-01 — every PHYS switch off = the production runtime (863f3fb)", { timeout: 600_000 }, () => {
  it(`plans: ${PROFILES.length} profiles generate the very same V2 plan`, () => {
    for (const { name, snap } of PROFILES) expect(plan(current, snap), name).toEqual(plan(production!, snap));
  });

  it("daily: KEEP / MODIFY / REPLACE of every planned session, every time limit — the very same result", () => {
    let cases = 0;
    const statuses = new Map<string, number>();
    const refused = new Map<string, number>();
    const refusedFrom = new Map<string, number>();
    for (const { name, snap } of PROFILES.filter((_, i) => i % 4 === 0)) {
      const generated = plan(production!, snap);
      if (!("status" in generated) || generated.status !== "generated") continue;
      const p = generated.plan;
      for (const s of p.weeks.flatMap((w) => w.sessions).filter((x) => x.kind !== "REST")) {
        const planned = { kind: s.kind, ...(s.loadProfile ? { loadProfile: s.loadProfile } : {}), ...(s.durationMin !== undefined && s.durationMin !== null ? { durationMin: s.durationMin } : {}) };
        const decisions: ["KEEP" | "MODIFY" | "REPLACE", BuildFinalPrescriptionV2Input["decision"]["finalSession"]][] = [["KEEP", planned]];
        if (s.loadProfile && LOWER[s.loadProfile]) decisions.push(["MODIFY", { ...planned, loadProfile: LOWER[s.loadProfile]! }]);
        if (typeof s.durationMin === "number" && s.durationMin > 30) decisions.push(["MODIFY", { ...planned, durationMin: s.durationMin - 15 }]);
        for (const target of REPLACE_TARGETS) decisions.push(["REPLACE", target]);
        for (const [decision, finalSession] of decisions) {
          // SPORT-SAFE-01 — production's result with no time limit says whether A04 made the planned dose a "modified" copy.
          const copy = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(generatedInput(production!, p, s, snap, decision, finalSession, null)));
          for (const minutes of TIME_LIMITS) {
            const prod = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(generatedInput(production!, p, s, snap, decision, finalSession, minutes)));
            const cur = outcome(() => current.buildFinalPrescriptionWithinTodayTimeV2(generatedInput(current, p, s, snap, decision, finalSession, minutes)));
            const label = `${name} ${s.date} ${s.kind} ${decision} ${JSON.stringify(finalSession)} ${minutes}`;
            if (unchangedModify(copy, s, decision)) {
              expect(cur, label).toEqual(refusalOf(copy, prod as current.FinalPrescriptionWithinTodayTimeV2Result, s, finalSession));
              const key = `${s.kind} ${s.loadProfile}→${finalSession.loadProfile} ${s.durationMin} min`;
              refused.set(key, (refused.get(key) ?? 0) + 1);
              const was = `production ${(prod as current.FinalPrescriptionWithinTodayTimeV2Result).timeConstraint?.action ?? "no time"}`;
              refusedFrom.set(was, (refusedFrom.get(was) ?? 0) + 1);
            } else expect(cur, label).toEqual(prod);
            const key = "thrown" in (prod as object) ? "thrown" : (prod as { status: string }).status;
            statuses.set(key, (statuses.get(key) ?? 0) + 1);
            cases += 1;
          }
        }
      }
    }
    note(`daily planned: ${cases} cases ${JSON.stringify(Object.fromEntries(statuses))}; SPORT-SAFE-01 refusals ${JSON.stringify(Object.fromEntries(refused))} ${JSON.stringify(Object.fromEntries(refusedFrom))}`);
    // SPORT-SAFE-01 — the one intended difference: only the endurance session already at the LIGHT duration.
    expect([...refused.keys()].sort()).toEqual(["AEROBIC_BASE MODERATE→LIGHT 45 min"]);
    // Coverage of the comparison itself: thousands of cases, every outcome kind represented.
    expect(cases).toBeGreaterThan(5000);
    expect(statuses.get("created") ?? 0).toBeGreaterThan(1000);
    expect(statuses.get("blocked") ?? 0).toBeGreaterThan(100);
  });

  it("daily: a manual session of every plannable kind and load, KEEP / MODIFY / REPLACE, every time limit — the very same result", () => {
    let cases = 0;
    let manualWithSession = 0;
    const manualRefused = new Map<string, number>();
    for (const { name, snap } of PROFILES.filter((_, i) => i % 6 === 0)) {
      const generated = plan(production!, snap);
      if (!("status" in generated) || generated.status !== "generated") continue;
      const p = generated.plan;
      const date = p.weeks[1]!.sessions[0]!.date;
      for (const kind of MANUAL_KINDS) {
        for (const loadProfile of [undefined, "LIGHT", "MODERATE", "HEAVY"] as const) {
          const finalSession = { kind, ...(loadProfile ? { loadProfile } : {}) };
          for (const decision of ["KEEP", "MODIFY", "REPLACE"] as const) {
            for (const minutes of TIME_LIMITS) {
              const prod = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(manualInput(production!, p, snap, date, decision, finalSession, minutes)));
              const cur = outcome(() => current.buildFinalPrescriptionWithinTodayTimeV2(manualInput(current, p, snap, date, decision, finalSession, minutes)));
              expect(cur, `${name} manual ${kind} ${loadProfile} ${decision} ${minutes}`).toEqual(prod);
              cases += 1;
            }
            // SPORT-SAFE-01R — the same MODIFY with the rider's session before M1 (one load higher, what M1 lowered):
            // production ignores it; the current runtime refuses only a document identical to that session's KEEP.
            const higher = loadProfile !== undefined ? HIGHER[loadProfile] : undefined;
            if (decision !== "MODIFY" || higher === undefined) continue;
            const manualSession = { kind, loadProfile: higher };
            const copy = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(manualInput(production!, p, snap, date, "MODIFY", finalSession, null, manualSession))) as current.FinalPrescriptionWithinTodayTimeV2Result;
            const keep = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(manualInput(production!, p, snap, date, "KEEP", manualSession, null))) as current.FinalPrescriptionWithinTodayTimeV2Result;
            const identical = copy.status === "created" && keep.status === "created" && current.canonicalSportContent(copy.finalPrescription.structure) === current.canonicalSportContent(keep.finalPrescription.structure);
            for (const minutes of TIME_LIMITS) {
              const label = `${name} manual ${kind} ${higher}→${loadProfile} MODIFY ${minutes}`;
              const prod = outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(manualInput(production!, p, snap, date, "MODIFY", finalSession, minutes, manualSession))) as current.FinalPrescriptionWithinTodayTimeV2Result;
              const cur = outcome(() => current.buildFinalPrescriptionWithinTodayTimeV2(manualInput(current, p, snap, date, "MODIFY", finalSession, minutes, manualSession)));
              if (identical && copy.status === "created") {
                const before = prod.timeConstraint?.before;
                expect(cur, label).toEqual({
                  status: "blocked",
                  code: "final_prescription_adaptation_not_defined",
                  detail: { reason: "modify_not_supported", planned: higher, final: loadProfile, durationMin: copy.effectiveDurationMin ?? null },
                  ...(prod.timeConstraint !== undefined ? { timeConstraint: { availableMinutes: prod.timeConstraint.availableMinutes, action: "not_evaluated", before, after: before } } : {}),
                });
                const key = `${kind} ${higher}→${loadProfile}`;
                manualRefused.set(key, (manualRefused.get(key) ?? 0) + 1);
              } else expect(cur, label).toEqual(prod);
              manualWithSession += 1;
            }
          }
        }
      }
    }
    note(`daily manual: ${cases} cases; with the session before M1: ${manualWithSession} cases, SPORT-SAFE-01R refusals ${JSON.stringify(Object.fromEntries(manualRefused))}`);
    // SPORT-SAFE-01R — the intended manual differences, exactly where the builder has no lever for M1's lower load:
    // endurance (fixed protocol RPE), a HEAVY DH (built at the MODERATE dose), active recovery (fixed dose; a load on it
    // is not plannable in /plan, reached here only). Force and the other kinds are really lighter, unchanged.
    expect([...manualRefused.keys()].sort()).toEqual([
      "AEROBIC_BASE HEAVY→MODERATE",
      "AEROBIC_BASE MODERATE→LIGHT",
      "DH_LIGHT HEAVY→MODERATE",
      "DH_TECHNICAL HEAVY→MODERATE",
      "RECOVERY_ACTIVE HEAVY→MODERATE",
      "RECOVERY_ACTIVE MODERATE→LIGHT",
    ]);
    expect(cases).toBeGreaterThan(3000);
  });

  it("counter-proof: the same comparison with every switch ON finds the PHYS differences (the comparison is sensitive)", () => {
    const ON = { daily: true, intervals: true, power: true, mobility: true };
    const generated = plan(production!, PROFILES[PROFILES.length - 2]!.snap);
    if (!("status" in generated) || generated.status !== "generated") throw new Error("plan");
    const p = generated.plan;
    const force = p.weeks.flatMap((w) => w.sessions).find((s) => s.kind === "STRENGTH_LOWER")!;
    const forceKeep = { kind: force.kind, loadProfile: force.loadProfile!, ...(force.durationMin ? { durationMin: force.durationMin } : {}) };
    const differs = (input: (r: Runtime) => BuildFinalPrescriptionV2Input & { availableMinutes: number | null }) =>
      JSON.stringify(outcome(() => current.buildFinalPrescriptionWithinTodayTimeV2({ ...input(current), phys: ON }))) !==
      JSON.stringify(outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(input(production!))));
    const snap = PROFILES[PROFILES.length - 2]!.snap;
    // Force under the rider's time (PHYS-01.1), a manual power / intervals / mobility session (PHYS-02 / 03 / 04).
    expect(differs((r) => generatedInput(r, p, force, snap, "KEEP", forceKeep, 45))).toBe(true);
    for (const kind of ["POWER", "AEROBIC_INTERVALS", "MOBILITY"]) {
      expect(differs((r) => manualInput(r, p, snap, force.date, "KEEP", { kind, loadProfile: kind === "MOBILITY" ? undefined : "MODERATE" } as never, null)), kind).toBe(true);
    }
    // And with every switch off, the very same inputs give the production result.
    expect(outcome(() => current.buildFinalPrescriptionWithinTodayTimeV2(generatedInput(current, p, force, snap, "KEEP", forceKeep, 45)))).toEqual(
      outcome(() => production!.buildFinalPrescriptionWithinTodayTimeV2(generatedInput(production!, p, force, snap, "KEEP", forceKeep, 45)))
    );
  });
});
